/**
 * One tiny real picture per admitted format (24 x 16 pixels, HEIC larger), for the
 * capability probe: preparing each one proves this machine can decode that
 * format, which a tool's presence on the search path does not. Generated by
 * test/fixtures/images/generate.py; the HEIC is written by Apple's encoder.
 * Each picture is a landscape of known shape, so a decoder that returns
 * something else has not decoded this.
 */

import type { StillImageFormat } from './still-image-formats.ts';

/**
 * The size each probe picture is. Every format but HEIC is 24 x 16. A HEIC
 * that small is refused by libheif's own security limit ("Image size exceeds
 * the maximum image size", seen on libheif 1.23 even for a genuine Apple
 * encode of 24 x 16), which would report HEIC as undecodable on a machine
 * that reads real photos; 64 x 64 and 128 x 96 decode fine, so the HEIC probe
 * picture is 128 x 96.
 */
export const STILL_IMAGE_PROBE_SIZES = {
  jpeg: { width: 24, height: 16 },
  png: { width: 24, height: 16 },
  heic: { width: 128, height: 96 },
  webp: { width: 24, height: 16 },
  gif: { width: 24, height: 16 },
  tiff: { width: 24, height: 16 },
  bmp: { width: 24, height: 16 },
} as const satisfies Readonly<Record<StillImageFormat, { width: number; height: number }>>;

export const STILL_IMAGE_PROBE_FIXTURES: Readonly<Record<StillImageFormat, string>> = {
  jpeg: '',
  png: 'iVBORw0KGgoAAAANSUhEUgAAABgAAAAQCAIAAACDRijCAAAALUlEQVR42mO8o6HBQAj4BCwgqIaJgUpg1KChaBCjRsUJgopOVGiMBvaoQfgAAEgnBVeLpAKIAAAAAElFTkSuQmCC',
  heic: '',
  webp: 'UklGRkIAAABXRUJQVlA4TDUAAAAvF8ADABcgEEi0wtifYhyFbCNAgvOn2D0IAoFEK9wRR5j/+CcREGTbTPKSRT1BRP9jG56ongA=',
  gif: 'R0lGODdhGAAQAIEAAPDw8Ch4yNwoKAAAACwAAAAAGAAQAEAIRgAFCBxIUGCAgwgTKlyIEIDDhxAdFpwogKHFixEzAqBY8CJCjgQ9imyoEeLIkhBBDhyp0qDIlhVfthx5EqXDmjZxotRZMiAAOw==',
  tiff: '',
  bmp: '',
};
